mapper.select:
SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth,t.teacher_id as teacherId, p.parent_id as parentId FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id where s.name like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id where s.type like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id where s.student_id like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id where s.clazz like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id,s.grade,s.img as image,p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex,s.create_time,s.update_time,s.status,s.birth FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id where s.status like concat('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

SELECT s.device_id, s.grade, s.img as image, p.name as parentName, s.student_id, t.name as teacherName, s.clazz, s.name, s.password, s.phone, s.sex, s.create_time, s.update_time, s.status, s.birth, t.teacher_id as teacherId, p.parent_id as parentId FROM student s JOIN teacher t ON s.teacher_id = t.teacher_id JOIN parent p ON s.parent_id = p.parent_id
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.clazz LIKE CONCAT('%', #{clazz}, '%')
AND s.student_id LIKE CONCAT('%', #{id}, '%')
AND s.phone = #{phone}
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
